CustomField.formula:
IF(
    /* Case 1: Work Item is assigned to a specific User */
    NOT(ISBLANK(AssignedUser__c)),

    /* Prefix with "User:" and display full name (handle missing First Name) */
    "User: " &
    IF(
        ISBLANK(AssignedUser__r.FirstName),
        AssignedUser__r.LastName,
        AssignedUser__r.FirstName & " " & AssignedUser__r.LastName
    ),

    /* Case 2: Work Item is assigned to a Queue */
    IF(
        NOT(ISBLANK(AssignedQueue__c)),

        /* Prefix with "Queue:" to distinguish from users in reports */
        "Queue: " &  AssignedQueue__r.Name ,

        /* Case 3: No assignment exists */
        "Unassigned"
    )
)
